const CACHE_NAME="c3-community-v3";self.addEventListener("install",t=>{self.skipWaiting()}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(e=>Promise.all(e.map(s=>{if(s!==CACHE_NAME)return caches.delete(s)})))),self.clients.claim()}),self.addEventListener("fetch",t=>{if(t.request.method==="GET"&&!t.request.url.startsWith("chrome-extension")){if(t.request.mode==="navigate"){t.respondWith(fetch(t.request).then(e=>{const s=e.clone();return caches.open(CACHE_NAME).then(c=>c.put(t.request,s)),e}).catch(()=>caches.match(t.request).then(e=>e||caches.match("/"))));return}t.respondWith(caches.match(t.request).then(e=>{const s=fetch(t.request).then(c=>{if(c&&c.status===200&&c.type==="basic"){const r=c.clone();caches.open(CACHE_NAME).then(h=>h.put(t.request,r))}return c}).catch(()=>{});return e||s}))}});
